-- ========================================================
-- 5. 문의 카테고리 & 문의게시판 24건 (답변대기 4건, 비밀글 3건, 답변완료 20건)
-- ========================================================

    qna_id, member_id, qna_category_id, qna_title, qna_content, qna_status, is_deleted, is_secret, qna_created_at
) VALUES
(1, 45, 2, '전입신고 시 세대주와 세대원 동시 이사 질문드립니다.', '부모님 댁에서 독립하여 저(세대원) 혼자 새 주소지로 이사하는 경우와, 가족 전원이 다 함께 이사하는 경우에 시뮬레이션에서 3단계 세대 구성원 선택 방법이 어떻게 다른가요? 연습 도중 헷갈려서 문의드립니다.', 'WAITING', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 45 MINUTE)),
(2, 82, 1, '비밀번호 재설정 메일이 스팸함에도 들어오지 않아요.', '비밀번호를 분실해서 비밀번호 찾기에서 가입 이메일을 입력하고 전송을 눌렀는데 10분이 지나도 인증 메일이 도착하지 않습니다. 혹시 학교/회사 이메일 도메인은 제한이 있나요?', 'WAITING', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 2 HOUR)),
(3, 114, 3, '상단 폰트 크기 4단계 조절 버튼 너무 편하고 좋습니다!', '어르신 복지관에서 디지털 행정 교육용으로 해봄 사이트를 활용하고 있습니다. 이전에는 글씨가 작아 화면을 확대해야 했는데, 이번에 상단에 더 크게, 가장 크게 4단계 드롭다운이 추가되어 큰 글씨로 교육하기 너무 좋아졌습니다! 개발팀에 감사 인사 전합니다.', 'WAITING', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 5 HOUR)),
(4, 210, 4, '전입신고 외에 확정일자 부여 시뮬레이션도 추가 계획이 있으신가요?', '전입신고와 함께 꼭 해야 하는 게 주민센터 확정일자 부여인데, 혹시 확정일자나 보증보험 관련 행정 절차도 향후 시뮬레이션으로 제작될 계획이 있는지 궁금합니다.', 'WAITING', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 14 HOUR)),
(5, 12, 2, '전입신고 3단계에서 이전 주소 조회가 안 됩니다.', '전입신고 연습을 진행하던 중에 3단계 이전 주소 입력에서 검색 버튼을 눌러도 주소가 나오지 않습니다. 어떻게 진행해야 하나요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 1 DAY)),
(6, 18, 1, '아이디를 변경하고 싶은데 가능한가요?', '가입할 때 설정한 아이디를 변경하고 싶은데 마이페이지에서 변경 메뉴를 찾지 못했습니다. 수정 방법이 궁금합니다.', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 2 DAY)),
(7, 33, 2, '[비밀글] 전입신고 시 가족관계증명서 제출 여부 문의', '비공개 문의입니다. 미성년자 자녀와 함께 세대주를 변경하며 전입할 때 별도의 가족관계증명서 첨부가 필요한지 시뮬레이션 안내문 확인차 문의드립니다.', 'ANSWERED', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 2 DAY)),
(8, 55, 3, '모바일 화면에서 버튼 글자가 조금 겹쳐 보입니다.', '스마트폰 브라우저로 접속해서 시뮬레이션을 진행해보니 다음 단계 이동 버튼 글자가 살짝 겹쳐 보입니다. 확인 부탁드립니다.', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 3 DAY)),
(9, 71, 2, '시뮬레이션 연습 결과는 어디서 다시 볼 수 있나요?', '전입신고 시뮬레이션을 끝까지 완료했는데, 제가 입력했던 결과 내용을 다시 확인하고 복습할 수 있는 메뉴가 있을까요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 4 DAY)),
(10, 94, 4, '새로운 행정 시나리오는 언제 추가되나요?', '전입신고와 주민등록증 재발급 외에 여권 발급이나 확정일자 부여 같은 다른 민원 절차도 추가될 예정인지 궁금합니다!', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 5 DAY)),
(11, 108, 2, '우편물 전입지 전송 서비스 신청 시 추가 비용이 드나요?', '시뮬레이션 마지막 단계에서 우편물 주소이전 서비스 신청 항목이 나오는데 실제 정부24에서도 유료인지 무료인지 궁금합니다.', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 6 DAY)),
(12, 125, 1, '[비밀글] 회원 탈퇴 후 동일 아이디로 재가입 가능한가요?', '개인 사정으로 탈퇴 후 다시 가입하려 하는데 탈퇴 즉시 기존 아이디로 재가입이 가능한지 궁금합니다.', 'ANSWERED', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 8 DAY)),
(13, 142, 2, '임대차계약서 제출 단계는 시뮬레이션에 없나요?', '실제 전입신고할 때는 임대차계약서를 파일로 첨부했던 기억이 있는데 해봄 시뮬레이션에서는 파일 첨부 과정이 생략된 건가요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 9 DAY)),
(14, 163, 3, '맥북 사파리 브라우저에서도 지원되나요?', 'macOS Safari 브라우저에서 도로명 주소 검색 팝업이 차단되는 현상이 있었는데 팝업 허용 후 잘 됩니다. 안내 문구가 있으면 좋겠습니다.', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 11 DAY)),
(15, 188, 2, '세대주 확인은 실제 정부24에서 어떻게 진행되나요?', '세대주가 아닌 세대원이 전입신고를 신청했을 때 세대주 확인은 문자로 오는지 카카오톡으로 오는지 궁금합니다.', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 13 DAY)),
(16, 204, 1, '로그인 세션 만료 시간이 몇 분인가요?', '연습 도중에 잠시 자리를 비웠더니 로그아웃이 되어 있었습니다. 보안을 위한 세션 유지 시간이 어떻게 설정되어 있나요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 15 DAY)),
(17, 230, 2, '다세대 주택 동/호수 입력 시 주의사항이 있나요?', '빌라나 다세대 주택의 경우 건축물대장상 호수와 실제 현관 호수가 다를 때 전입신고 기준이 어떻게 되는지 시뮬레이션 팁으로도 다뤄주시면 좋겠습니다.', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 18 DAY)),
(18, 255, 3, '[비밀글] 관리자 답변 알림은 이메일로 발송되나요?', '문의글을 남겼을 때 답변이 등록되면 가입한 이메일로도 알림 메일이 오는지 궁금합니다.', 'ANSWERED', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 20 DAY)),
(19, 278, 4, '공공기관 강의용으로 사이트 소개 자료를 받을 수 있을까요?', '구청 평생학습관에서 디지털 취약계층 대상 민원서비스 교육 강사로 일하고 있습니다. 해봄 서비스를 수업에 소개하고 싶은데 소개서가 있을까요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 22 DAY)),
(20, 310, 2, '초본 상 주소와 실제 사는 곳이 다를 때 연습 팁', '전입신고 시 직전 거주지 주소는 반드시 주민등록등초본 상의 주소여야 하나요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 25 DAY)),
(21, 335, 3, '다크모드 지원 계획도 있으신지 궁금합니다.', '야간에 눈이 피로해서 다크모드를 선호하는데 혹시 추후 화면 모드 전환 기능도 검토 중이신가요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 28 DAY)),
(22, 360, 2, '정부24 실제 사이트와 인터페이스가 똑같아서 놀랐어요!', '정부24 전입신고 화면과 거의 흡사하게 구현되어 있어서 부모님께 먼저 연습시켜 드리고 실전 신고 성공했습니다! 정말 유익한 사이트입니다.', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 30 DAY)),
(23, 388, 1, '이름 개명 후 마이페이지 정보 수정 방법', '최근 법원에서 개명 허가를 받았는데 해봄 마이페이지에서 이름을 바꾸려면 본인인증을 다시 해야 하나요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 35 DAY)),
(24, 412, 2, '세대 합가(두 세대가 하나로 합쳐짐) 시뮬레이션 문의', '기존 세대주 밑으로 다른 세대가 통째로 들어가는 세대 합가의 경우에도 이 시뮬레이션으로 충분히 연습할 수 있을까요?', 'ANSWERED', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 40 DAY));

-- ========================================================
-- 6. 문의 답변 20건 (관리자 3명이 나누어 작성)
-- ========================================================
    qna_id, member_id, qna_answer_content, qna_answer_created_at
) VALUES
(5, 1, '안녕하세요, 해봄 운영팀 박해봄입니다.\n\n3단계 이전 주소 조회의 경우, 시뮬레이션에서는 사전 정보 단계에서 설정하신 가상 주소가 기본 바인딩됩니다. 만약 검색창이 비어있다면 [주소 검색] 버튼을 누른 뒤 도로명 또는 동 이름을 입력하시면 가상 주소 목록에서 손쉽게 선택하실 수 있습니다.\n\n추가 문의사항이 있으시면 언제든 남겨주세요. 감사합니다!', DATE_SUB(NOW(), INTERVAL 23 HOUR)),
(6, 2, '안녕하세요, 해봄 운영팀 이정원입니다.\n\n해봄 서비스의 로그인 아이디는 회원 식별 고유키로 사용되어 회원가입 후에는 직접 변경이 어렵습니다. 부득이하게 아이디 변경이 필요하신 경우, 탈퇴 후 신규 아이디로 재가입해 주시거나 고객센터로 계정 초기화 요청을 남겨주시면 신속히 처리해 드리겠습니다.\n\n감사합니다.', DATE_SUB(NOW(), INTERVAL 1 DAY)),
(7, 3, '안녕하세요, 해봄 고객지원팀 김민지입니다.\n\n미성년 자녀와 동반 전입 시 실제 행정망(정부24)에서는 전산상 가족관계가 자동 조회되므로 별도의 증명서 제출이 대부분 생략됩니다. 단, 행정정보 공동이용에 동의하지 않거나 시스템 조회 불가 시 가족관계증명서 제출이 필요할 수 있으며, 해봄 시뮬레이션 3단계 안내문에서도 이 점을 상세히 다루고 있으니 참고 바랍니다.\n\n감사합니다.', DATE_SUB(NOW(), INTERVAL 1 DAY)),
(8, 2, '안녕하세요, 해봄 운영팀 이정원입니다.\n\n모바일 반응형 레이아웃에서 일부 글자가 겹쳐 보이는 현상을 제보해 주셔서 감사드립니다. 해당 이슈는 모바일 하단 플로팅 액션바 패딩 조정 업데이트에 반영되어 현재 정상 수정되었습니다. 앞으로도 불편한 점이 있으시면 편하게 말씀해 주세요!', DATE_SUB(NOW(), INTERVAL 2 DAY)),
(9, 1, '안녕하세요, 해봄 운영팀 박해봄입니다.\n\n전입신고 시뮬레이션을 성실히 완주해 주셔서 감사드립니다!\n완료하신 연습 이력은 상단 메뉴의 [마이페이지 > 나의 연습 이력]에서 언제든지 단계별 작성 내용과 입력 요약본을 다시 확인하고 복습하실 수 있습니다.\n\n유익한 학습 시간이 되시길 바랍니다!', DATE_SUB(NOW(), INTERVAL 3 DAY)),
(10, 1, '안녕하세요, 해봄 운영팀 박해봄입니다.\n\n해봄 서비스에 깊은 관심을 가져주셔서 감사드립니다. 현재 주민등록증 재발급 시나리오의 후속으로 [여권 온라인 재발급] 및 [확정일자 신청] 시나리오를 기획 및 개발 중에 있습니다. 다음 분기 업데이트를 기대해 주세요!', DATE_SUB(NOW(), INTERVAL 4 DAY)),
(11, 3, '안녕하세요, 해봄 고객지원팀 김민지입니다.\n\n정부24를 통한 우편물 주소이전 서비스(주거이전 우편물 전송 서비스)는 최초 3개월간 동일 권역 내 전송은 무료로 제공됩니다. 시뮬레이션 4단계에서도 무료/유료 전환 기준 및 서비스 신청 팁을 함께 안내해 드리고 있으니 실전 신청 시 참고하시기 바랍니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 5 DAY)),
(12, 2, '안녕하세요, 해봄 운영팀 이정원입니다.\n\n해봄 서비스는 탈퇴 처리 즉시 회원의 개인정보를 파기(논리 삭제)하므로 동일한 아이디로 즉시 재가입이 가능합니다. 단, 기존에 진행하셨던 시뮬레이션 이력과 마이페이지 데이터는 복구되지 않는 점 유의해 주시기 바랍니다.\n\n감사합니다.', DATE_SUB(NOW(), INTERVAL 7 DAY)),
(13, 1, '안녕하세요, 해봄 운영팀 박해봄입니다.\n\n좋은 질문 감사드립니다! 해봄 시뮬레이션은 핵심 민원 신청 절차(세대주 확인, 주소 입력, 세대원 이동)의 흐름을 익히는 것에 중점을 두고 있어 복잡한 파일 첨부 과정은 가상 완료 처리로 간소화하였습니다. 실전 신고 시에는 계약서 PDF 또는 사진 파일이 필요하므로 유의사항 탭을 꼭 확인해 주세요!', DATE_SUB(NOW(), INTERVAL 8 DAY)),
(14, 2, '안녕하세요, 해봄 운영팀 이정원입니다.\n\n사파리 브라우저 팝업 차단 안내 피드백 감사드립니다. 도로명주소 팝업 API 호출 시 사파리의 팝업 자동 차단 정책에 대한 안내 가이드를 주소 검색 버튼 하단 툴팁으로 보강하도록 개선 조치하였습니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 10 DAY)),
(15, 3, '안녕하세요, 해봄 고객지원팀 김민지입니다.\n\n실제 정부24에서 세대원 신청 시 세대주 확인은 세대주 휴대전화로 전송되는 알림톡(문자) 인증 또는 세대주가 정부24에 직접 공인인증서로 로그인하여 세대주 확인 메뉴에서 승인하는 방식으로 진행됩니다. 시뮬레이션 3단계 가이드에서도 해당 절차를 확인하실 수 있습니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 12 DAY)),
(16, 2, '안녕하세요, 해봄 운영팀 이정원입니다.\n\n해봄 서비스의 보안 로그인 세션 만료 시간은 마지막 요청 후 60분으로 설정되어 있습니다. 장시간 자리 비움 시 민원 정보 보호를 위해 자동 로그아웃되오니 학습 중 임시 저장 버튼을 적극 활용해 주시기 바랍니다. 감사합니다.', DATE_SUB(NOW(), INTERVAL 14 DAY)),
(17, 1, '안녕하세요, 해봄 운영팀 박해봄입니다.\n\n매우 중요한 실무 포인트입니다! 다세대 주택은 반드시 건축물대장 및 등기부등본 상의 호수(예: B01호, 101호)를 기준으로 정확히 신고해야 대항력과 우선변제권이 보호됩니다. 시뮬레이션 4단계 도움말 툴팁에 관련 상세 팁을 보강해 두었습니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 17 DAY)),
(18, 3, '안녕하세요, 해봄 고객지원팀 김민지입니다.\n\n네, 맞습니다. 관리자가 고객님의 문의에 정성껏 답변을 등록하면 가입하신 이메일 주소로 답변 완료 알림 메일이 자동 발송됩니다. 마이페이지에서도 언제든 답변 내역을 실시간으로 열람하실 수 있습니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 19 DAY)),
(19, 1, '안녕하세요, 해봄 운영팀 박해봄입니다.\n\n디지털 취약계층을 위해 뜻깊은 교육에 힘써주셔서 진심으로 감사드립니다! 해봄 서비스는 비영리 공공 교육 목적으로 누구나 자유롭게 활용하실 수 있습니다. 강의용 시뮬레이션 교안 및 소개 리플릿 PDF를 고객센터 대표 메일(admin@haebom.co.kr)로 요청해 주시면 발송해 드리겠습니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 21 DAY)),
(20, 3, '안녕하세요, 해봄 고객지원팀 김민지입니다.\n\n네, 맞습니다! 전입신고 시 이사하기 전 살던 곳은 현재 본인의 주민등록등초본 상의 법정 주소를 기준으로 조회 및 입력해야 행정 오류 없이 다음 단계로 넘어갈 수 있습니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 24 DAY)),
(21, 2, '안녕하세요, 해봄 운영팀 이정원입니다.\n\n다크모드 제안 감사드립니다! 현재 상단 폰트 크기 4단계 조절 시스템에 이어, 야간 시력 보호를 위한 고대비/다크모드 테마 기능을 UI 개선 백로그에 등록하여 검토 중에 있습니다. 더 쾌적한 서비스를 만들겠습니다. 감사합니다!', DATE_SUB(NOW(), INTERVAL 27 DAY)),
(22, 1, '안녕하세요, 해봄 운영팀 박해봄입니다.\n\n부모님의 실전 전입신고 성공 소식을 들으니 개발팀 전원이 큰 보람을 느낍니다! 해봄은 앞으로도 국민 누구나 두려움 없이 디지털 행정을 누릴 수 있도록 더 친절하고 완성도 높은 시뮬레이션을 만들어 가겠습니다. 따뜻한 후기 감사드립니다!', DATE_SUB(NOW(), INTERVAL 29 DAY)),
(23, 2, '안녕하세요, 해봄 운영팀 이정원입니다.\n\n개명 후 정보 변경은 마이페이지 [내 정보 수정] 메뉴에서 본인인증(또는 주민등록번호 실명인증 연동)을 다시 진행하시면 통신사/행정망에 등록된 최신 실명으로 자동 갱신됩니다. 문의사항이 있으시면 언제든 찾아주세요. 감사합니다!', DATE_SUB(NOW(), INTERVAL 34 DAY)),
(24, 3, '안녕하세요, 해봄 고객지원팀 김민지입니다.\n\n세대 합가의 경우에도 4단계에서 기존 세대주가 있는 곳으로 이사 옵션을 선택하신 후 기존 세대주와의 관계를 설정하시면 동일하게 연습하실 수 있습니다. 복잡한 민원도 해봄과 함께 차근차근 익혀보세요! 감사합니다.', DATE_SUB(NOW(), INTERVAL 39 DAY));

-- ========================================================
-- 7. 관리자 최근 활동 로그 14건 (운영자 3명 골고루 참여 & 바로가기 연동)
-- ========================================================



